paras.text:
/* static and automatic variables program*/
#include <conio.h>
#include <iostream.h>
void demo(){
auto int Auto_Var = 0; // automatic variable
static int Static_Var = 0; // static variable
cout<<"Auto ="<<Auto_Var<< ","<< "Static="<<Static_Var<<endl;
++ Auto_Var; ++ Static_Var; }
int main()
{
int i=0;
while( i < 3 )
{ demo(); i++; }
getch();
return 0;
}

